const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const ids = ['cleave', 'shield', 'slam', 'arrow', 'trap', 'shuriken', 'fireball', 'icering', 'orb', 'beam'];
const data = Object.fromEntries(ids.map(id => {
  const bytes = fs.readFileSync(path.join(root, 'assets/warrior-art3', id + '.webp'));
  return [id, 'data:image/webp;base64,' + bytes.toString('base64')];
}));
fs.writeFileSync(path.join(root, 'src/warrior-art-data.js'),
  '// Generated by node dev/pack-warrior-art.cjs.\nconst WARRIOR_ART_DATA = ' + JSON.stringify(data, null, 2) + ';\n');
